	// output buffer is left silent so the mic is not echoed back.
	sourceNode.connect(processor);
	processor.connect(captureContext.destination);
	setState("listening");

	return {
		get state() {
			return state;
		},
		async stop() {
			cleanup();
		},
	};
}

